import { tags } from "typia";

import { IErpHrmTask } from "./IErpHrmTask";
import { IErpHrmTimelog } from "./IErpHrmTimelog";
import { IErpHrmTimer } from "./IErpHrmTimer";
import { IErpHrmTimesheet } from "./IErpHrmTimesheet";

/**
 * Dashboard response containing personal metrics for all authenticated users and organizational metrics for users with report:view permission.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IErpHrmDashboard = {
  /**
   * Personal time tracking metrics for the authenticated employee, including hours logged today and this week, active timer status, recent time entries, pending timesheet for the current week, and assigned tasks with open or in-progress status.
   *
     * @x-autobe-specification Aggregate from: erp_hrm_timelogs (hours_today,
     *   hours_this_week, recent_timelogs), erp_hrm_timers (active_timer),
     *   erp_hrm_timesheets (pending_timesheet), erp_hrm_tasks (assigned_tasks).
     *   Always returned for authenticated users. Join via erp_hrm_employee_id
     *   from session context.
   */
  personalMetrics: IErpHrmDashboard.IPersonalMetric;

  /**
   * Organizational overview metrics available only to users with report:view permission, showing aggregate statistics about employees, time tracking, pending approvals, high-budget projects, and top performers.
   *
     * @x-autobe-specification Aggregate from: erp_hrm_employees
     *   (active_employee_count), erp_hrm_timelogs (total_hours_this_week),
     *   erp_hrm_timesheets (pending_approval_count), erp_hrm_projects
     *   (budget_utilization_over_80_percent), erp_hrm_timelogs with
     *   erp_hrm_employees (top_5_performers). Scoped to current organization
     *   from session context. Only included when report:view permission exists.
   */
  organizationalMetrics?:
    | IErpHrmDashboard.IOrganizationalMetric
    | null
    | undefined;
};
export namespace IErpHrmDashboard {
  /**
   * Personal time tracking metrics for the authenticated employee, including hours logged today and this week, active timer status, recent time entries, pending timesheet for the current week, and assigned tasks with open or in-progress status.
   */
  export type IPersonalMetric = {
    /**
     * Total minutes logged by the employee today.
     *
         * @x-autobe-specification SUM(duration_minutes) from erp_hrm_timelogs
         *   WHERE erp_hrm_employee_id = session.employee_id AND date =
         *   current_date. Returns total minutes logged today by the
         *   authenticated employee.
     */
    hoursToday: number & tags.Type<"int32">;

    /**
     * Total minutes logged by the employee this week (Monday to Sunday).
     *
         * @x-autobe-specification SUM(duration_minutes) from erp_hrm_timelogs
         *   WHERE erp_hrm_employee_id = session.employee_id AND week containing
         *   current_date (Monday to Sunday). Returns total minutes logged this
         *   week by the authenticated employee.
     */
    hoursThisWeek: number & tags.Type<"int32">;

    /**
     * Currently running timer for the authenticated employee. Null if no timer is active.
     *
         * @x-autobe-specification Single row from erp_hrm_timers WHERE
         *   erp_hrm_employee_id = session.employee_id AND timer has no
         *   associated timelog (timer still running). Returns
         *   IErpHrmTimer.ISummary when active timer exists, null otherwise.
     */
    activeTimer: IErpHrmTimer.ISummary | null;

    /**
     * The 5 most recent timelog entries for the authenticated employee.
     *
         * @x-autobe-specification Last 5 rows from erp_hrm_timelogs WHERE
         *   erp_hrm_employee_id = session.employee_id ORDER BY created_at DESC.
         *   Returns array of IErpHrmTimelog.ISummary objects.
     */
    recentTimelogs: IErpHrmTimelog.ISummary[];

    /**
     * The timesheet for the current week if it exists as draft or submitted. Null if no timesheet has been created.
     *
         * @x-autobe-specification Single row from erp_hrm_timesheets WHERE
         *   erp_hrm_employee_id = session.employee_id AND week_start_date =
         *   current Monday AND status IN ('draft', 'submitted'). Returns
         *   IErpHrmTimesheet.ISummary when timesheet exists, null otherwise.
     */
    pendingTimesheet?: IErpHrmTimesheet.ISummary | null | undefined;

    /**
     * Tasks assigned to the employee with status 'open' or 'in-progress'.
     *
         * @x-autobe-specification Rows from erp_hrm_tasks WHERE
         *   erp_hrm_employee_id = session.employee_id AND status IN ('open',
         *   'in-progress') ORDER BY due_date ASC, priority DESC. Returns array
         *   of IErpHrmTask.ISummary objects.
     */
    assignedTasks: IErpHrmTask.ISummary[];
  };

  /**
   * Organizational dashboard metrics showing aggregate statistics about employees, time tracking activity, pending approvals, high-budget projects, and top performers for the current organization.
   */
  export type IOrganizationalMetric = {
    /**
     * Count of employees with active status in the current organization.
     *
         * @x-autobe-specification COUNT(*) FROM erp_hrm_employees WHERE
         *   erp_hrm_organization_id = :organizationId AND status = 'active' AND
         *   deleted_at IS NULL. Scoped to current organization from session
         *   context.
     */
    activeEmployeeCount: number & tags.Type<"int32">;

    /**
     * Total hours logged by all employees this week (Monday 00:00:00 to Sunday 23:59:59).
     *
         * @x-autobe-specification SUM(timelogs.duration_minutes) / 60.0 FROM
         *   erp_hrm_timelogs timelogs JOIN erp_hrm_employees employees ON
         *   timelogs.erp_hrm_employee_id = employees.id WHERE
         *   employees.erp_hrm_organization_id = :organizationId AND
         *   timelogs.date >= :weekStartMonday AND timelogs.date <=
         *   :weekEndSunday. Uses current server week boundaries
         *   (Monday-Sunday).
     */
    totalHoursThisWeek: number;

    /**
     * Number of timesheets in 'submitted' status awaiting manager approval.
     *
         * @x-autobe-specification COUNT(*) FROM erp_hrm_timesheets WHERE
         *   erp_hrm_employee_id IN (SELECT id FROM erp_hrm_employees WHERE
         *   erp_hrm_organization_id = :organizationId) AND status =
         *   'submitted'. Counts all submitted timesheets owned by employees in
         *   the current organization.
     */
    pendingApprovalCount: number & tags.Type<"int32">;

    /**
     * List of projects where logged hours exceed 80% of their configured budget hours.
     *
         * @x-autobe-specification SELECT projects.id, projects.name,
         *   projects.budget_hours, SUM(timelogs.duration_minutes)/60.0 AS
         *   actual_hours FROM erp_hrm_projects projects JOIN erp_hrm_timelogs
         *   timelogs ON projects.id = timelogs.erp_hrm_project_id WHERE
         *   projects.erp_hrm_organization_id = :organizationId AND
         *   projects.budget_hours IS NOT NULL GROUP BY projects.id HAVING
         *   SUM(timelogs.duration_minutes)/60.0 >= (projects.budget_hours *
         *   0.8). Excludes projects with null budget_hours.
     */
    budgetUtilizationOver80Percent: IErpHrmDashboard.IBudgetUtilizationItem[];

    /**
     * Top 5 employees ranked by total hours logged this week, showing employee name and hours.
     *
         * @x-autobe-specification SELECT employees.id, members.display_name,
         *   SUM(timelogs.duration_minutes)/60.0 AS hours FROM erp_hrm_employees
         *   employees JOIN erp_hrm_members members ON
         *   employees.erp_hrm_member_id = members.id JOIN erp_hrm_timelogs
         *   timelogs ON employees.id = timelogs.erp_hrm_employee_id WHERE
         *   employees.erp_hrm_organization_id = :organizationId AND
         *   timelogs.date >= :weekStartMonday AND timelogs.date <=
         *   :weekEndSunday GROUP BY employees.id, members.display_name ORDER BY
         *   hours DESC LIMIT 5. Uses current server week boundaries.
     */
    top5Performers: IErpHrmDashboard.ITopPerformer[];
  };

  /**
   * Budget utilization metrics for a single project showing configured budget hours versus actual hours logged, enabling budget tracking and alert visualization on the organization dashboard.
   */
  export type IBudgetUtilizationItem = {
    /**
     * Unique identifier of the project.
     *
         * @x-autobe-specification Project identifier from aggregation query:
         *   SELECT projects.id FROM erp_hrm_projects JOIN erp_hrm_timelogs ON
         *   projects.id = timelogs.erp_hrm_project_id WHERE
         *   projects.budget_hours IS NOT NULL GROUP BY projects.id.
     */
    id: string & tags.Format<"uuid">;

    /**
     * Name of the project.
     *
         * @x-autobe-specification Project name from aggregation query: SELECT
         *   projects.name FROM erp_hrm_projects JOIN erp_hrm_timelogs WHERE
         *   projects.budget_hours IS NOT NULL.
     */
    name: string;

    /**
     * Total estimated hours allocated for the project.
     *
         * @x-autobe-specification Budget hours from aggregation query: SELECT
         *   projects.budget_hours FROM erp_hrm_projects WHERE
         *   projects.budget_hours IS NOT NULL.
     */
    budgetHours: number;

    /**
     * Total hours actually logged against this project, calculated by summing all timelog durations in minutes and dividing by 60.
     *
         * @x-autobe-specification Aggregated computation:
         *   SUM(timelogs.duration_minutes)/60.0 FROM erp_hrm_timelogs WHERE
         *   timelogs.erp_hrm_project_id = projects.id. This field is computed
         *   from the JOIN between erp_hrm_projects and erp_hrm_timelogs tables,
         *   grouped by project. Only projects with budget_hours configured and
         *   actual hours >= 80% of budget threshold are included.
     */
    actualHours: number;
  };

  /**
   * Top employee performer ranked by total hours logged during the current week.
   */
  export type ITopPerformer = {
    /**
     * Display name of the employee.
     *
         * @x-autobe-specification Derived from erp_hrm_members.display_name
         *   column via JOIN with erp_hrm_employees. Part of aggregation query:
         *   SELECT members.display_name.
     */
    displayName: string;

    /**
     * Unique identifier of the employee.
     *
         * @x-autobe-specification Derived from erp_hrm_employees.id column via
         *   JOIN with erp_hrm_members. Part of aggregation query: SELECT
         *   employees.id.
     */
    employeeId: string;

    /**
     * Total hours logged by the employee this week, calculated as sum of duration_minutes divided by 60.
     *
         * @x-autobe-specification Computed as
         *   SUM(timelogs.duration_minutes)/60.0 from erp_hrm_timelogs. Grouped
         *   by employee, scoped to current organization and current week
         *   (Monday-Sunday).
     */
    hours: number;
  };
}
